+        storedFieldLoaders.get("foo.one").advanceToDoc(0);
+        storedFieldLoaders.get("foo.one").load(List.of(45L, 46L));
+        storedFieldLoaders.get("foo.two").advanceToDoc(0);
+        storedFieldLoaders.get("foo.two").load(List.of(1L));
+
