+        storedFieldLoaders.get("foo.two").advanceToDoc(0);
+        storedFieldLoaders.get("foo.two").load(List.of(1L));
+
+        var result = XContentBuilder.builder(XContentType.JSON.xContent());
+        result.startObject();
+        sut.write(result);
+        result.endObject();
+
+        assertEquals("""
+            {"foo":[45,46,1]}""", Strings.toString(result));
+    }
